describe('Onboarding Tour Modal', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('.onboarding-tour-button').click(); // Trigger the onboarding tour modal
    });

    it('should display the onboarding tour modal with the first step', () => {
        cy.get('.onboarding-tour-modal').should('be.visible');
        cy.get('.onboarding-tour-step').first().should('contain.text', 'Welcome to the onboarding tour!');
    });

    it('should advance to the next step when the next button is clicked', () => {
        cy.get('.onboarding-tour-next-button').click();
        cy.get('.onboarding-tour-step').eq(1).should('contain.text', 'Here is how to use the application.');
    });

    it('should not advance if the next button is disabled', () => {
        cy.get('.onboarding-tour-next-button').should('be.disabled');
        cy.get('.onboarding-tour-next-button').click();
        cy.get('.onboarding-tour-step').first().should('contain.text', 'Welcome to the onboarding tour!'); // Ensure it stays on the first step
    });
});
